        self.connections = []
        self.totalPoints = 0
        self.createdDate = Date()
        self.specialFormations = []
    }

    static func createStarterStars() -> [Star] {
        var starterStars: [Star] = []

        // Add 3 starter stars in a triangle formation
        let positions = [
            CGPoint(x: 0, y: -50),
            CGPoint(x: -43, y: 25),
            CGPoint(x: 43, y: 25)
        ]

        for i in 0..<3 {
            var star = Star(
                duration: 5,
                startTime: Date(),
                position: positions[i],
                magnitude: .dim
            )
            star.isComplete = true
            star.brightness = 0.5
            star.currentMinutes = 5

            starterStars.append(star)
        }

        return starterStars
    }
}

