    @Published var selectedWebDomains: Set<WebDomainToken> = []

    private let center = AuthorizationCenter.shared
    private let store = ManagedSettingsStore()
    private let activityMonitor = FocusFlowActivityMonitor()
    private var isRequestingAuthorization = false

    init() {
        // Don't request authorization automatically - wait for explicit user action
        // This prevents the keyboard issue with the passcode dialog
        checkAuthorizationStatus()
    }

    private func checkAuthorizationStatus() {
        // Check if already authorized without requesting
        Task { @MainActor in
            switch center.authorizationStatus {
            case .approved:
                self.isAuthorized = true
            case .denied, .notDetermined:
                self.isAuthorized = false
            @unknown default:
                self.isAuthorized = false
            }
        }
    }

    func requestAuthorization() async {
        // Prevent multiple simultaneous authorization requests
        guard !isRequestingAuthorization else {
            print("⚠️ [ScreenTimeManager] Authorization already in progress, skipping duplicate request")
            return
        }

        // Check if already authorized
        if center.authorizationStatus == .approved {
            await MainActor.run {
                self.isAuthorized = true
            }
            return
        }
