        let radius: Double // meters
        let blockedApps: [String]
        let isActive: Bool
        let schedule: Schedule?

        struct Schedule: Codable {
            let startTime: Date
            let endTime: Date
            let daysOfWeek: [Int] // 1 = Sunday, 7 = Saturday

            func isActiveNow() -> Bool {
                let now = Date()
                let calendar = Calendar.current
                let currentDay = calendar.component(.weekday, from: now)

                let currentTimeComponents = calendar.dateComponents([.hour, .minute], from: now)
                let startComponents = calendar.dateComponents([.hour, .minute], from: startTime)
                let endComponents = calendar.dateComponents([.hour, .minute], from: endTime)

                guard let currentHour = currentTimeComponents.hour,
                      let currentMinute = currentTimeComponents.minute,
                      let startHour = startComponents.hour,
                      let startMinute = startComponents.minute,
                      let endHour = endComponents.hour,
                      let endMinute = endComponents.minute else {
                    return false
                }

                let currentMinutes = currentHour * 60 + currentMinute
                let startMinutes = startHour * 60 + startMinute
                let endMinutes = endHour * 60 + endMinute

                if startMinutes <= endMinutes {
                    guard daysOfWeek.contains(currentDay) else { return false }
                    return currentMinutes >= startMinutes && currentMinutes <= endMinutes
                } else {
                    let previousDay = currentDay == 1 ? 7 : currentDay - 1
                    let inLateWindow = daysOfWeek.contains(currentDay) && currentMinutes >= startMinutes
                    let inEarlyWindow = daysOfWeek.contains(previousDay) && currentMinutes <= endMinutes
                    return inLateWindow || inEarlyWindow
                }
            }
        }

