    private let sharedDefaults = UserDefaults(suiteName: "group.com.romirjain.focusflow")

    override func intervalDidStart(for activity: DeviceActivityName) {
        super.intervalDidStart(for: activity)
        logEvent("Focus session started")
    }

    override func intervalDidEnd(for activity: DeviceActivityName) {
        super.intervalDidEnd(for: activity)
        sharedDefaults?.removeObject(forKey: "overrideExpiry")
        sharedDefaults?.set(0, forKey: "sessionBlockedAttempts")
        logEvent("Focus session ended")
    }

    override func eventDidReachThreshold(_ event: DeviceActivityEvent.Name, activity: DeviceActivityName) {
        super.eventDidReachThreshold(event, activity: activity)

        // Check for temporary override
        if let overrideExpiry = sharedDefaults?.object(forKey: "overrideExpiry") as? Date {
            if Date() < overrideExpiry {
                return // User has active override
            } else {
                sharedDefaults?.removeObject(forKey: "overrideExpiry")
            }
        }

        // Signal main app to show intervention
        sharedDefaults?.set(true, forKey: "showIntervention")
        sharedDefaults?.set("Blocked App", forKey: "lastBlockedAppName")
        sharedDefaults?.set(Date(), forKey: "lastBlockedAppAttempt")

        // Increment attempt counter
        let attempts = sharedDefaults?.integer(forKey: "sessionBlockedAttempts") ?? 0
        sharedDefaults?.set(attempts + 1, forKey: "sessionBlockedAttempts")

        logEvent("Blocked app attempt #\(attempts + 1)")
    }


    private func logEvent(_ message: String) {
        #if DEBUG
